    public function fetch_markets($params = array()): PromiseInterface {
        return Async\async(self::do_fetch_markets(...))($params);
    }

    private function do_fetch_markets($params = array()) {
        /**
         * retrieves data on all markets for bit2me
         *
         * @see https://api.bit2me.com/docs/pro/api-reference/marketdata/v2/trading/market-config/get
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->marketEnabled] filter by market state, one of 'enabled', 'enabled_at', 'frozen', 'restricted'
         * @return {array[]} an array of objects representing market data
         */
        $response = Async\await($this->publicGetV2TradingMarketConfig($params));
        //
        //     [
        //         {
        //             "id": "5daf7851-c883-4e34-ad1a-52a8bb7651e3",
        //             "symbol": "BTC/EUR",
        //             "marketEnabled": "enabled",
        //             "marketEnabledAt": null,
        //             "minAmount": 0.00006,
        //             "maxAmount": 20,
        //             "minPrice": 7500,
        //             "maxPrice": 7500000,
        //             "minOrderSize": 1,
        //             "tickSize": 0.1,
        //             "initialPrice": 0,
        //             "pricePrecision": 1,
        //             "amountPrecision": 8,
        //             "feeMakerPercentage": 0,
        //             "feeTakerPercentage": 0
        //         }
        //     ]
        //
        return $this->parse_markets($response);
    }

    public function parse_market(array $market): array {
        $id = $this->safe_string($market, 'symbol', '');
        $parts = explode('/', $id);
        $baseId = $this->safe_string($parts, 0);
        $quoteId = $this->safe_string($parts, 1);
        $base = $this->safe_currency_code($baseId);
        $quote = $this->safe_currency_code($quoteId);
        $status = $this->safe_string($market, 'marketEnabled');
        $tradingFees = $this->safe_value($this->fees, 'trading');
        return $this->safe_market_structure(array(
            'id' => $id,
            'symbol' => $base . '/' . $quote,
            'base' => $base,
            'quote' => $quote,
            'settle' => null,
            'baseId' => $baseId,
            'quoteId' => $quoteId,
            'settleId' => null,
            'type' => 'spot',
            'spot' => true,
            'margin' => false,
            'swap' => false,
            'future' => false,
            'option' => false,
            'active' => ($status === 'enabled'),
            'contract' => false,
            'linear' => null,
            'inverse' => null,
            'contractSize' => null,
            'expiry' => null,
            'expiryDatetime' => null,
            'strike' => null,
            'optionType' => null,
            'taker' => $this->safe_number($tradingFees, 'taker'),
            'maker' => $this->safe_number($tradingFees, 'maker'),
            'precision' => array(
                'amount' => $this->parse_number($this->parse_precision($this->safe_string($market, 'amountPrecision'))),
                'price' => $this->parse_number($this->parse_precision($this->safe_string($market, 'pricePrecision'))),
                'cost' => null,
            ),
            'limits' => array(
                'leverage' => array(
                    'min' => null,
                    'max' => null,
                ),
                'amount' => array(
                    'min' => $this->safe_number($market, 'minAmount'),
                    'max' => $this->safe_number($market, 'maxAmount'),
                ),
                'price' => array(
                    'min' => $this->safe_number($market, 'minPrice'),
                    'max' => $this->safe_number($market, 'maxPrice'),
                ),
                'cost' => array(
                    'min' => $this->safe_number($market, 'minOrderSize'),
                    'max' => null,
                ),
            ),
            'created' => $this->parse8601($this->safe_string($market, 'marketEnabledAt')),
            'info' => $market,
        ));
    }

    public function fetch_currencies($params = array()): PromiseInterface {
        return Async\async(self::do_fetch_currencies(...))($params);
    }

    private function do_fetch_currencies($params = array()) {
        /**
         * fetches all available currencies on an exchange
         *
         * @see https://api.bit2me.com/docs/wallet/rest-overview
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {boolean} [$params->includeTestnet] default false, when true testnet $assets are included
         * @return {array} an associative dictionary of currencies
         */
        list($includeTestnet, $query) = $this->handle_option_bool_and_params($params, 'fetchCurrencies', 'includeTestnet', false);
        $request = array(
            'includeTestnet' => ($includeTestnet) ? 'true' : 'false',
        );
        $promises = array(
            $this->publicGetV2CurrencyAssets($this->extend($request, $query)),
            $this->publicGetV1WalletSettingsAssets($query),
        );
        $responses = Async\await(Promise\all($promises));
        //
        // assets
        //
        //     {
        //         "BTC": {
        //             "symbol": "BTC",
        //             "name": "Bitcoin",
        //             "slug": "bitcoin",
        //             "mainwebUri": "bitcoin",
        //             "uriScheme": "bitcoin",
        //             "hexColor": "#eca24d",
        //             "assetType": "currency",
        //             "addressRegex": "^([13][a-km-zA-HJ-NP-Z1-9]{25,34})|...",
        //             "hasImage": true,
        //             "hasPaymentRequest": true,
        //             "isERC20Token": false,
        //             "image": "/crypto-icons/v8/svg/btc-circle-solid-default.svg",
        //             "network": "BITCOIN",
        //             "enabled": true,
        //             "lite": false,
        //             "pairsWith": [ "EUR" ],
        //             "ticker": true,
        //             "loanable": true,
        //             "exponent": 8, // optional
        //             "createdAt": "2024-10-08", // optional
        //             "removedAt": "2025-05-22T00:00:00.000Z" // optional, set for delisted assets
        //         }
        //     }
        //
        // wallet settings
        //
        //     [
        //         {
        //             "symbol": "BTC",
        //             "actions": [ "deposit", "deposit-app", "deposit-web", "earn", "instant", "purchase", "transfer", "withdrawal" ]
        //         }
        //     ]
        //
        $assets = $this->safe_dict($responses, 0, array());
        $settings = $this->safe_list($responses, 1, array());
        $settingsById = $this->index_by($settings, 'symbol');
        $ids = is_array($assets) ? array_keys($assets) : array();
        $result = array();
        for ($i = 0; $i < count($ids); $i++) {
            $id = $ids[$i];
            $asset = $this->safe_dict($assets, $id, array());
            $assetSettings = $this->safe_dict($settingsById, $id, array());
            // an operation that is not listed for an asset is not available for it
            $actions = $this->safe_list($assetSettings, 'actions', array());
            $currency = $this->parse_currency($this->extend($asset, array( 'actions' => $actions )));
            $code = $currency['code'];
            $result[$code] = $currency;
        }
        return $result;
    }

    public function parse_currency(array $rawCurrency): array {
        $id = $this->safe_string($rawCurrency, 'symbol');
        $code = $this->safe_currency_code($id);
        $assetType = $this->safe_string($rawCurrency, 'assetType');
        $enabled = $this->safe_bool($rawCurrency, 'enabled', false);
        $removedAt = $this->safe_string($rawCurrency, 'removedAt');
        $active = $enabled && ($removedAt === null);
        $actions = $this->safe_list($rawCurrency, 'actions', array());
        $deposit = $this->in_array('deposit', $actions);
        $withdraw = $this->in_array('withdrawal', $actions);
        // the exponent is only published for a handful of assets, fall back to the usual decimals
        $defaultExponent = ($assetType === 'fiat') ? '2' : '8';
        $precision = $this->parse_number($this->parse_precision($this->safe_string($rawCurrency, 'exponent', $defaultExponent)));
        $networks = array();
        $networkId = $this->safe_string($rawCurrency, 'network');
        $networkCode = $this->network_id_to_code($networkId, $code);
        if ($networkCode !== null) {
            $networks[$networkCode] = array(
                'info' => $rawCurrency,
                'id' => $networkId,
                'network' => $networkCode,
                'active' => $active,
                'deposit' => $deposit,
                'withdraw' => $withdraw,
                'fee' => null,
                'precision' => $precision,
                'limits' => array(
                    'withdraw' => array(
                        'min' => null,
                        'max' => null,
                    ),
                    'deposit' => array(
                        'min' => null,
                        'max' => null,
                    ),
                ),
            );
        }
        return $this->safe_currency_structure(array(
            'info' => $rawCurrency,
            'id' => $id,
            'code' => $code,
            'name' => $this->safe_string($rawCurrency, 'name'),
            'active' => $active,
            'deposit' => $deposit,
            'withdraw' => $withdraw,
            'networks' => $networks,
            'fee' => null,
            'precision' => $precision,
            'type' => ($assetType === 'fiat') ? 'fiat' : 'crypto',
            'limits' => array(
                'amount' => array(
                    'min' => null,
                    'max' => null,
                ),
                'deposit' => array(
                    'min' => null,
                    'max' => null,
                ),
                'withdraw' => array(
                    'min' => null,
                    'max' => null,
                ),
            ),
        ));
    }

    public function fetch_tickers(?array $symbols = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_tickers(...))($symbols, $params);
    }

    private function do_fetch_tickers(?array $symbols = null, $params = array()) {
        /**
         * fetches price tickers for multiple markets, statistical information calculated over the past 24 hours for each market
         *
         * @see https://api.bit2me.com/docs/pro/api-reference/marketdata/v2/trading/tickers/get
         *
         * @param {string[]} [$symbols] unified $symbols of the markets to fetch the ticker for, all market tickers are returned if not assigned
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a dictionary of [ticker structures](https://docs.ccxt.com/#/?id=ticker-structure)
         */
        Async\await($this->load_markets());
        $marketSymbols = $this->market_symbols($symbols);
        $response = Async\await($this->publicGetV2TradingTickers($params));
        //
        //     [
        //         {
        //             "timestamp": 1793711134437,
        //             "symbol": "BTC/EUR",
        //             "open": 69219.9,
        //             "close": 69085.4,
        //             "bid": 69085.4,
        //             "ask": 69085.5,
        //             "percentage": -0.19,
        //             "high": 69613.8,
        //             "low": 68111,
        //             "baseVolume": 658.2554895,
        //             "quoteVolume": 45221164.74541575
        //         }
        //     ]
        //
        return $this->parse_tickers($response, $marketSymbols);
    }

    public function fetch_ticker(string $symbol, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_ticker(...))($symbol, $params);
    }

    private function do_fetch_ticker(string $symbol, $params = array()) {
        /**
         * fetches a price $ticker, a statistical calculation with the information calculated over the past 24 hours for a specific $market
         *
         * @see https://api.bit2me.com/docs/pro/api-reference/marketdata/v2/trading/tickers/get
         *
         * @param {string} $symbol unified $symbol of the $market to fetch the $ticker for
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a [$ticker structure](https://docs.ccxt.com/#/?id=$ticker-structure)
         */
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        $request = array(
            'symbol' => $market['id'],
        );
        $response = Async\await($this->publicGetV2TradingTickers($this->extend($request, $params)));
        //
        //     [
        //         {
        //             "timestamp": 1793711134437,
        //             "symbol": "BTC/EUR",
        //             "open": 69219.9,
        //             "close": 69085.4,
        //             "bid": 69085.4,
        //             "ask": 69085.5,
        //             "percentage": -0.19,
        //             "high": 69613.8,
        //             "low": 68111,
        //             "baseVolume": 658.2554895,
        //             "quoteVolume": 45221164.74541575
        //         }
        //     ]
        //
        $ticker = $this->safe_dict($response, 0, array());
        return $this->parse_ticker($ticker, $market);
    }

    public function parse_ticker(array $ticker, ?array $market = null): array {
        //
        //     {
        //         "timestamp": 1793711134437,
        //         "symbol": "BTC/EUR",
        //         "open": 69219.9,
        //         "close": 69085.4,
        //         "bid": 69085.4,
        //         "ask": 69085.5,
        //         "percentage": -0.19,
        //         "high": 69613.8,
        //         "low": 68111,
        //         "baseVolume": 658.2554895,
        //         "quoteVolume": 45221164.74541575
        //     }
        //
        $marketId = $this->safe_string($ticker, 'symbol');
        $symbol = $this->safe_symbol($marketId, $market);
        $timestamp = $this->safe_integer($ticker, 'timestamp');
        $last = $this->safe_string($ticker, 'close');
        return $this->safe_ticker(array(
            'symbol' => $symbol,
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'high' => $this->safe_string($ticker, 'high'),
            'low' => $this->safe_string($ticker, 'low'),
            'bid' => $this->safe_string($ticker, 'bid'),
            'bidVolume' => null,
            'ask' => $this->safe_string($ticker, 'ask'),
            'askVolume' => null,
            'vwap' => null,
            'open' => $this->safe_string($ticker, 'open'),
            'close' => $last,
            'last' => $last,
            'previousClose' => null,
            'change' => null,
            'percentage' => $this->safe_string($ticker, 'percentage'),
            'average' => null,
            'baseVolume' => $this->safe_string($ticker, 'baseVolume'),
            'quoteVolume' => $this->safe_string($ticker, 'quoteVolume'),
            'info' => $ticker,
        ), $market);
    }

    public function fetch_order_book(string $symbol, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_order_book(...))($symbol, $limit, $params);
    }

    private function do_fetch_order_book(string $symbol, ?int $limit = null, $params = array()) {
        /**
         * fetches information on open orders with bid (buy) and ask (sell) prices, volumes and other data
         *
         * @see https://api.bit2me.com/docs/pro/api-reference/marketdata/v2/trading/order-book/get
         *
         * @param {string} $symbol unified $symbol of the $market to fetch the order book for
         * @param {int} [$limit] not used by bit2me.fetchOrderBook, the endpoint always returns up to 100 levels per side
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} A dictionary of [order book structures](https://docs.ccxt.com/#/?id=order-book-structure) indexed by $market symbols
         */
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        $request = array(
            'symbol' => $market['id'],
        );
        $response = Async\await($this->publicGetV2TradingOrderBook($this->extend($request, $params)));
        //
        //     {
        //         "bids": [ [ 69058.9, 0.19431333 ], [ 69058.8, 0.0001448 ] ],
        //         "asks": [ [ 69059.0, 0.00284291 ], [ 69060.1, 0.1 ] ],
        //         "symbol": "BTC/EUR",
        //         "timestamp": 1793711134413
        //     }
        //
        $timestamp = $this->safe_integer($response, 'timestamp');
        return $this->parse_order_book($response, $market['symbol'], $timestamp, 'bids', 'asks', 0, 1);
    }

    public function fetch_trades(string $symbol, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_trades(...))($symbol, $since, $limit, $params);
    }

    private function do_fetch_trades(string $symbol, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * get the list of most recent trades for a particular $symbol
         *
         * @see https://api.bit2me.com/docs/pro/api-reference/marketdata/v1/trading/trade/last/get
         *
         * @param {string} $symbol unified $symbol of the $market to fetch trades for
         * @param {int} [$since] timestamp in ms of the earliest trade to fetch
         * @param {int} [$limit] the maximum amount of trades to fetch, default 50, max 50
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {Trade[]} a list of [trade structures](https://docs.ccxt.com/#/?id=public-trades)
         */
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        $request = array(
            'symbol' => $market['id'],
        );
        if ($limit !== null) {
            $request['limit'] = min($limit, 50);
        }
        $response = Async\await($this->publicGetV1TradingTradeLast($this->extend($request, $params)));
        //
        //     [
        //         [ "sell", 69085.4, 0.00284291, 1793711134413 ],
        //         [ "buy", 69083.4, 0.00060614, 1793711113677 ]
        //     ]
        //
        // the exchange returns the newest trades first, reverse them so that trades sharing a timestamp keep their execution order
        $reversed = array();
        $length = count($response);
        for ($i = 0; $i < $length; $i++) {
            $reversed[] = $response[$length - 1 - $i];
        }
        return $this->parse_trades($reversed, $market, $since, $limit);
    }

    public function parse_trade(mixed $trade, ?array $market = null): array {
        //
        // fetchTrades (public)
        //
        //     [ "sell", 69085.4, 0.00284291, 1793711134413 ]
        //
        // fetchMyTrades, fetchOrderTrades (private)
        //
        //     {
        //         "amount": 0.24,
        //         "amountCurrency": "BTC",
        //         "clientOrderId": null,
        //         "cost": 15600.12,
        //         "costEuro": 15600.12,
        //         "createdAt": "2024-05-07T14:09:02.310Z",
        //         "feeAmount": 15.60012,
        //         "feeCurrency": "EUR",
        //         "feePercentage": 0.1,
        //         "feePercentageDiscount": 0, // fetchOrderTrades only
        //         "id": "4278a86a-53e7-4997-9102-01646ae8954a",
        //         "isMaker": true,
        //         "orderId": "536ee1dc-528a-419e-9c00-5e04c010658d",
        //         "orderType": "limit",
        //         "price": 65000.5,
        //         "priceCurrency": "EUR",
        //         "side": "buy",
        //         "spaceCenterLevelId": null, // fetchOrderTrades only
        //         "symbol": "BTC/EUR"
        //     }
        //
        if ((gettype($trade) === 'array' && array_keys($trade) === array_keys(array_keys($trade)))) {
            $publicSide = $this->safe_string_lower($trade, 0);
            $publicPrice = $this->safe_string($trade, 1);
            $publicAmount = $this->safe_string($trade, 2);
            $publicTimestamp = $this->safe_integer($trade, 3);
            $resolvedMarket = $this->safe_market(null, $market);
            return $this->safe_trade(array(
                'info' => $trade,
                'id' => null,
                'symbol' => $resolvedMarket['symbol'],
                'timestamp' => $publicTimestamp,
                'datetime' => $this->iso8601($publicTimestamp),
                'order' => null,
                'type' => null,
                'side' => $publicSide,
                'takerOrMaker' => null,
                'price' => $publicPrice,
                'amount' => $publicAmount,
                'cost' => null,
                'fee' => null,
            ), $resolvedMarket);
        }
        $marketId = $this->safe_string($trade, 'symbol');
        $privateMarket = $this->safe_market($marketId, $market);
        $timestamp = $this->parse8601($this->safe_string($trade, 'createdAt'));
        $isMaker = $this->safe_bool($trade, 'isMaker');
        $takerOrMaker = null;
        if ($isMaker !== null) {
            $takerOrMaker = ($isMaker) ? 'maker' : 'taker';
        }
        $fee = null;
        $feeCost = $this->safe_string($trade, 'feeAmount');
        if ($feeCost !== null) {
            $feeRate = null;
            $feePercentage = $this->safe_string($trade, 'feePercentage');
            if ($feePercentage !== null) {
                $feeRate = Precise::string_div($feePercentage, '100');
            }
            $fee = array(
                'cost' => $feeCost,
                'currency' => $this->safe_currency_code($this->safe_string($trade, 'feeCurrency')),
                'rate' => $feeRate,
            );
        }
        return $this->safe_trade(array(
            'info' => $trade,
            'id' => $this->safe_string($trade, 'id'),
            'symbol' => $privateMarket['symbol'],
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'order' => $this->safe_string($trade, 'orderId'),
            'type' => $this->parse_order_type($this->safe_string($trade, 'orderType')),
            'side' => $this->safe_string_lower($trade, 'side'),
            'takerOrMaker' => $takerOrMaker,
            'price' => $this->safe_string($trade, 'price'),
            'amount' => $this->safe_string($trade, 'amount'),
            'cost' => $this->safe_string($trade, 'cost'),
            'fee' => $fee,
        ), $privateMarket);
    }

    public function fetch_ohlcv(string $symbol, $timeframe = '1m', ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_ohlcv(...))($symbol, $timeframe, $since, $limit, $params);
    }

    private function do_fetch_ohlcv(string $symbol, $timeframe = '1m', ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * fetches historical candlestick data containing the open, high, low, and close price, and the volume of a $market
         *
         * @see https://api.bit2me.com/docs/pro/api-reference/marketdata/v1/trading/candle/get
         *
         * @param {string} $symbol unified $symbol of the $market to fetch OHLCV data for
         * @param {string} $timeframe the length of time each candle represents
         * @param {int} [$since] timestamp in ms of the earliest candle to fetch
         * @param {int} [$limit] the maximum amount of candles to fetch, default 1000, max 1000
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {int} [$params->until] timestamp in ms of the latest candle to fetch
         * @param {boolean} [$params->paginate] default false, when true will automatically $paginate by calling this endpoint multiple times. See in the docs all the [available parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-$params)
         * @return {int[][]} A list of candles ordered as timestamp, open, high, low, close, volume
         */
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        list($paginate, $paramsPaginate) = $this->handle_option_bool_and_params($params, 'fetchOHLCV', 'paginate', false);
        $maxLimit = 1000;
        if ($paginate) {
            return Async\await($this->fetch_paginated_call_deterministic('fetchOHLCV', $symbol, $since, $limit, $timeframe, $paramsPaginate, $maxLimit));
        }
        $requestLimit = ($limit === null) ? $maxLimit : min($limit, $maxLimit);
        list($until, $paramsUntil) = $this->handle_param_integer($paramsPaginate, 'until');
        $request = array(
            'symbol' => $market['id'],
            'interval' => $this->safe_string($this->timeframes, $timeframe, $timeframe),
            'limit' => $requestLimit,
        );
        if ($since !== null) {
            $request['startTime'] = $since;
        } else {
            // the endpoint returns the oldest candles first, so request a window that covers `limit` candles
            $duration = $this->parse_timeframe($timeframe) * 1000;
            if ($until !== null) {
                $request['startTime'] = $until - $requestLimit * $duration;
            } else {
                $request['startTime'] = $this->milliseconds() - $requestLimit * $duration;
            }
        }
        if ($until !== null) {
            $request['endTime'] = $until;
        }
        $response = Async\await($this->publicGetV1TradingCandle($this->extend($request, $paramsUntil)));
        //
        //     [
        //         [ 1793628000000, 69397.5, 69549.9, 69200.1, 69334.1, 20.37762874 ],
        //         [ 1793631600000, 69334, 69613.8, 68923.4, 69137.8, 22.29039127 ]
        //     ]
        //
        return $this->parse_ohlcvs($response, $market, $timeframe, $since, $limit);
    }

    public function parse_ohlcv(mixed $ohlcv, ?array $market = null): array {
        //
        //     [ 1793628000000, 69397.5, 69549.9, 69200.1, 69334.1, 20.37762874 ]
        //
        return array(
            $this->safe_integer($ohlcv, 0),
            $this->safe_number($ohlcv, 1),
            $this->safe_number($ohlcv, 2),
            $this->safe_number($ohlcv, 3),
            $this->safe_number($ohlcv, 4),
            $this->safe_number($ohlcv, 5),
        );
    }

    public function fetch_balance($params = array()): PromiseInterface {
        return Async\async(self::do_fetch_balance(...))($params);
    }

    private function do_fetch_balance($params = array()) {
        /**
         * query for balance and get the amount of funds available for trading or funds locked in orders
         *
         * @see https://api.bit2me.com/docs/pro/api-reference/funding/v1/trading/wallet/balance/get
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->symbols] comma-separated currency codes, only those wallets are returned
         * @return {array} a [balance structure](https://docs.ccxt.com/#/?id=balance-structure)
         */
        Async\await($this->load_markets());
        $response = Async\await($this->privateGetV1TradingWalletBalance($params));
        //
        //     [
        //         {
        //             "balance": 1350.5,
        //             "blockedBalance": 0,
        //             "createdAt": "2023-09-13T14:05:42.149Z",
        //             "currency": "EUR",
        //             "id": "3a9f1c2d-7e4b-4f6a-8c1d-2b3e4f5a6b7c",
        //             "rawBalance": "1350.5",
        //             "rawBlockedBalance": "0",
        //             "userId": "2bf436fc-43e6-459a-b647-6b446f72ad96"
        //         }
        //     ]
        //
        return $this->parse_balance_list($response);
    }

    public function parse_balance_list(array $response): array {
        $result = array(
            'info' => $response,
        );
        for ($i = 0; $i < count($response); $i++) {
            $wallet = $response[$i];
            $currencyId = $this->safe_string($wallet, 'currency');
            $code = $this->safe_currency_code($currencyId);
            $account = $this->account();
            // balance is the amount available for trading, blockedBalance is reserved by open orders and bots
            $account['free'] = $this->safe_string_2($wallet, 'rawBalance', 'balance');
            $account['used'] = $this->safe_string_2($wallet, 'rawBlockedBalance', 'blockedBalance');
            if ($code !== null) {
                $result[$code] = $account;
            }
        }
        return $this->safe_balance($result);
    }

    public function create_order(string $symbol, string $type, string $side, float $amount, ?float $price = null, $params = array()): PromiseInterface {
        return Async\async(self::do_create_order(...))($symbol, $type, $side, $amount, $price, $params);
    }

    private function do_create_order(string $symbol, string $type, string $side, float $amount, ?float $price = null, $params = array()) {
        /**
         * create a trade order
         *
         * @see https://api.bit2me.com/docs/pro/api-reference/trading/v1/trading/order/post
         *
         * @param {string} $symbol unified $symbol of the $market to create an order in
         * @param {string} $type 'market' or 'limit'
         * @param {string} $side 'buy' or 'sell'
         * @param {float} $amount how much you want to trade in units of the base currency
         * @param {float} [$price] the $price at which the order is to be fulfilled, in units of the quote currency, required for limit orders, for $market buy orders it is used to compute the cost to spend ($amount * $price)
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {float} [$params->triggerPrice] the $price at which a stop-limit order is activated, requires a limit $price
         * @param {float} [$params->stopLossPrice] the trigger $price of a stop loss, placed as a stop-limit order at the limit $price, or as the stop loss leg of an OCO when takeProfitPrice is also set
         * @param {float} [$params->takeProfitPrice] the trigger $price of a take profit, placed as a stop-limit order at the limit $price, or as the take profit leg of an OCO when stopLossPrice is also set
         * @param {float} [$params->stopLimitPrice] OCO only, the limit $price of the stop loss leg, defaults to the $price argument and then to stopLossPrice
         * @param {float} [$params->cost] for $market orders only, the $amount to trade in units of the quote currency, overrides $amount
         * @param {string} [$params->timeInForce] 'GTC' (default) or 'FOK' (limit orders only), IOC is not available on bit2me
         * @param {boolean} [$params->postOnly] true to place a post-only limit order
         * @param {string} [$params->clientOrderId] a unique identifier for the order
         * @return {array} an [order structure](https://docs.ccxt.com/#/?id=order-structure), for an OCO the take profit leg is returned and both legs are available in info, cancelling one leg does not cancel the other
         */
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        $request = $this->create_order_request($symbol, $type, $side, $amount, $price, $params);
        $response = Async\await($this->privatePostV1TradingOrder($request));
        //
        // oco, the take profit limit leg first and the stop loss stop-limit leg second, linked by orderGroupId
        //
        //     [
        //         { "id": "59b27fb6-...", "orderType": "limit", "status": "open", "price": 95928.16, "stopPrice": 0, "orderGroupId": "9a28690c-...", ... },
        //         { "id": "514bf92e-...", "orderType": "stop-limit", "status": "inactive", "price": 50892.91, "stopPrice": 51630.49, "orderGroupId": "9a28690c-...", ... }
        //     ]
        //
        if ((gettype($response) === 'array' && array_keys($response) === array_keys(array_keys($response)))) {
            $takeProfitLeg = $this->safe_dict($response, 0, array());
            $ocoOrder = $this->parse_order($takeProfitLeg, $market);
            $ocoOrder['info'] = $response;
            return $ocoOrder;
        }
        //
        //     {
        //         "cancelReason": null,
        //         "clientOrderId": null,
        //         "cost": 0,
        //         "createdAt": "2024-05-07T14:08:30.961Z",
        //         "feeAmount": 0,
        //         "feeCurrency": "EUR",
        //         "filledAmount": 0,
        //         "id": "536ee1dc-528a-419e-9c00-5e04c010658d",
        //         "orderAmount": 0.35,
        //         "orderGroupId": null,
        //         "orderType": "limit",
        //         "postOnly": null,
        //         "price": 65000.5,
        //         "side": "buy",
        //         "status": "open",
        //         "stopPrice": 0,
        //         "symbol": "BTC/EUR",
        //         "timeInForce": "GTC",
        //         "updatedAt": "2024-05-07T14:08:30.961Z",
        //         "userId": "2bf436fc-43e6-459a-b647-6b446f72ad96"
        //     }
        //
        return $this->parse_order($this->extend(array(), $response), $market);
    }

    public function create_order_request(string $symbol, string $type, string $side, float $amount, ?float $price = null, $params = array()): array {
        /**
         * @ignore
         * helper function to build the $request body for createOrder
         * @param {string} $symbol unified $symbol of the $market to create an order in
         * @param {string} $type 'market' or 'limit'
         * @param {string} $side 'buy' or 'sell'
         * @param {float} $amount how much you want to trade in units of the base currency
         * @param {float} [$price] the $price at which the order is to be fulfilled, in units of the quote currency
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} the $request body
         */
        $market = $this->market($symbol);
        $isMarketOrder = ($type === 'market');
        $stopLossPrice = $this->safe_string($params, 'stopLossPrice');
        $takeProfitPrice = $this->safe_string($params, 'takeProfitPrice');
        $stopLimitPrice = $this->safe_string($params, 'stopLimitPrice');
        $isOco = ($stopLossPrice !== null) && ($takeProfitPrice !== null);
        // a lone stop loss or take profit is a stop-limit order, the exchange triggers it in either direction
        $triggerPrice = $this->safe_string_n($params, array( 'triggerPrice', 'stopPrice', 'stopLossPrice', 'takeProfitPrice' ));
        $cost = $this->safe_string($params, 'cost');
        // every order placed through the library is tagged with the broker id, CCXT-<id>
        $clientOrderId = $this->safe_string($params, 'clientOrderId');
        if ($clientOrderId === null) {
            $brokerId = $this->safe_string($this->options, 'brokerId', 'CCXT');
            $prefix = $brokerId . '-';
            $clientOrderId = $prefix . $this->uuid();
        }
        $query = $this->omit($params, array( 'triggerPrice', 'stopPrice', 'stopLossPrice', 'takeProfitPrice', 'stopLimitPrice', 'cost', 'clientOrderId' ));
        $postOnly = false;
        list($postOnly, $query) = $this->handle_post_only($isMarketOrder, false, $query);
        $timeInForce = $this->safe_string_upper($query, 'timeInForce');
        $query = $this->omit($query, 'timeInForce');
        $request = array(
            'symbol' => $market['id'],
            'side' => $side,
            'orderType' => $type,
        );
        if ($isOco) {
            if ($side !== 'sell') {
                throw new InvalidOrder($this->id . ' createOrder() only supports OCO orders on the sell side');
            }
            if ($isMarketOrder) {
                throw new InvalidOrder($this->id . ' createOrder() OCO legs are limit orders, use the limit type');
            }
            $request['orderType'] = 'oco';
            $request['amount'] = $this->amount_to_precision($symbol, $amount);
            $request['takeProfitPrice'] = $this->price_to_precision($symbol, $takeProfitPrice);
            $request['stopPrice'] = $this->price_to_precision($symbol, $stopLossPrice);
            $stopLossLimit = $stopLimitPrice;
            if ($stopLossLimit === null) {
                if ($price !== null) {
                    $stopLossLimit = $this->number_to_string($price);
                } else {
                    $stopLossLimit = $stopLossPrice;
                }
            }
            $request['stopLimitPrice'] = $this->price_to_precision($symbol, $stopLossLimit);
        } elseif ($isMarketOrder) {
            if ($triggerPrice !== null) {
                throw new InvalidOrder($this->id . ' createOrder() does not support stop-market orders, use a limit price to place a stop-limit order');
            }
            if ($cost !== null) {
                $request['amount'] = $this->cost_to_precision($symbol, $cost);
                $request['amountInQuote'] = true;
            } elseif (($side === 'buy') && ($price !== null)) {
                // the unified convention for market buy orders, the cost to spend is amount * price
                $quoteAmount = Precise::string_mul($this->number_to_string($amount), $this->number_to_string($price));
                $request['amount'] = $this->cost_to_precision($symbol, $quoteAmount);
                $request['amountInQuote'] = true;
            } else {
                $request['amount'] = $this->amount_to_precision($symbol, $amount);
            }
        } else {
            if ($price === null) {
                throw new ArgumentsRequired($this->id . ' createOrder() requires a price argument for a ' . $type . ' order');
            }
            $request['amount'] = $this->amount_to_precision($symbol, $amount);
            $request['price'] = $this->price_to_precision($symbol, $price);
            if ($triggerPrice !== null) {
                $request['orderType'] = 'stop-limit';
                $request['stopPrice'] = $this->price_to_precision($symbol, $triggerPrice);
            }
        }
        if ($postOnly) {
            $request['postOnly'] = true;
        }
        if ($timeInForce !== null) {
            $request['timeInForce'] = $timeInForce;
        }
        if (!$isOco) {
            // the exchange does not accept a clientOrderId on oco orders
            $request['clientOrderId'] = $clientOrderId;
        }
        return $this->extend($request, $query);
    }

