    private function do_fetch_order(string $id, ?string $symbol = null, $params = array()) {
        /**
         * fetches information on an order made by the user
         *
         * @see https://api.bit2me.com/docs/pro/api-reference/trading/v1/trading/order/id/get
         * @see https://api.bit2me.com/docs/pro/api-reference/trading/v1/trading/order/get
         *
         * @param {string} $id the order $id
         * @param {string} [$symbol] not used by bit2me.fetchOrder
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->clientOrderId] fetch the order by its client order $id instead of its $id
         * @return {array} an [order structure](https://docs.ccxt.com/#/?$id=order-structure)
         */
        Async\await($this->load_markets());
        $market = null;
        if ($symbol !== null) {
            $market = $this->market($symbol);
        }
        $clientOrderId = $this->safe_string($params, 'clientOrderId');
        if ($clientOrderId !== null) {
            $query = $this->omit($params, 'clientOrderId');
            $requestByClientId = array(
                'clientOrderId' => $clientOrderId,
            );
            $orders = Async\await($this->privateGetV1TradingOrder($this->extend($requestByClientId, $query)));
            $numOrders = count($orders);
            if ($numOrders === 0) {
                throw new OrderNotFound($this->id . ' fetchOrder() could not find an order with clientOrderId ' . $clientOrderId);
            }
            $first = $this->safe_dict($orders, 0, array());
            return $this->parse_order($first, $market);
        }
        $request = array(
            'id' => $id,
        );
        $response = Async\await($this->privateGetV1TradingOrderId($this->extend($request, $params)));
        //
        //     {
        //         "cancelReason": null,
        //         "clientOrderId": null,
        //         "cost": 15600.12,
        //         "createdAt": "2024-05-07T14:08:30.961Z",
        //         "feeAmount": 15.60012,
        //         "feeCurrency": "EUR",
        //         "filledAmount": 0.24,
        //         "id": "536ee1dc-528a-419e-9c00-5e04c010658d",
        //         "orderAmount": 0.35,
        //         "orderGroupId": null,
        //         "orderType": "limit",
        //         "postOnly": null,
        //         "price": 65000.5,
        //         "side": "buy",
        //         "status": "open",
        //         "stopPrice": 0,
        //         "symbol": "BTC/EUR",
        //         "timeInForce": "GTC",
        //         "updatedAt": "2024-05-07T14:09:02.310Z",
        //         "userId": "2bf436fc-43e6-459a-b647-6b446f72ad96"
        //     }
        //
        return $this->parse_order($response, $market);
    }

