    public function parse_order_status(?string $status): ?string {
        $statuses = array(
            'open' => 'open',
            'inactive' => 'open', // stop-limit order waiting for its trigger
            'filled' => 'closed',
            'cancelled' => 'canceled',
        );
        return $this->safe_string($statuses, $status, $status);
    }

    public function parse_order_type(?string $type): ?string {
        $types = array(
            'limit' => 'limit',
            'market' => 'market',
            'stop-limit' => 'limit',
        );
        return $this->safe_string($types, $type, $type);
    }

    public function parse_order(array $order, ?array $market = null): array {
        //
        // createOrder, cancelOrder, fetchOrder, fetchOrders
        //
        //     {
        //         "cancelReason": null,
        //         "clientOrderId": null,
        //         "cost": 15600.12,
        //         "createdAt": "2024-05-07T14:08:30.961Z",
        //         "feeAmount": 15.60012,
        //         "feeCurrency": "EUR",
        //         "filledAmount": 0.24,
        //         "id": "536ee1dc-528a-419e-9c00-5e04c010658d",
        //         "orderAmount": 0.35,
        //         "orderGroupId": null,
        //         "orderType": "limit",
        //         "postOnly": null,
        //         "price": 65000.5,
        //         "side": "buy",
        //         "status": "open",
        //         "stopPrice": 0,
        //         "symbol": "BTC/EUR",
        //         "timeInForce": "GTC",
        //         "updatedAt": "2024-05-07T14:09:02.310Z",
        //         "userId": "2bf436fc-43e6-459a-b647-6b446f72ad96"
        //     }
        //
        $marketId = $this->safe_string($order, 'symbol');
        $resolvedMarket = $this->safe_market($marketId, $market);
        $timestamp = $this->parse8601($this->safe_string($order, 'createdAt'));
        $rawType = $this->safe_string($order, 'orderType');
        $fee = null;
        $feeCost = $this->safe_number($order, 'feeAmount');
        if ($feeCost !== null) {
            $fee = array(
                'cost' => $feeCost,
                'currency' => $this->safe_currency_code($this->safe_string($order, 'feeCurrency')),
            );
        }
        return $this->safe_order(array(
            'info' => $order,
            'id' => $this->safe_string($order, 'id'),
            'clientOrderId' => $this->safe_string($order, 'clientOrderId'),
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'lastTradeTimestamp' => null,
            'lastUpdateTimestamp' => $this->parse8601($this->safe_string($order, 'updatedAt')),
            'symbol' => $resolvedMarket['symbol'],
            'type' => $this->parse_order_type($rawType),
            'timeInForce' => $this->safe_string($order, 'timeInForce'),
            'postOnly' => $this->safe_bool($order, 'postOnly'),
            'reduceOnly' => null,
            'side' => $this->safe_string_lower($order, 'side'),
            // market orders are stored with a price of 0
            'price' => $this->omit_zero($this->safe_string($order, 'price')),
            'triggerPrice' => $this->omit_zero($this->safe_string($order, 'stopPrice')),
            'amount' => $this->safe_string($order, 'orderAmount'),
            'cost' => $this->safe_string($order, 'cost'),
            'average' => null,
            'filled' => $this->safe_string($order, 'filledAmount'),
            'remaining' => null,
            'status' => $this->parse_order_status($this->safe_string($order, 'status')),
            'fee' => $fee,
            'trades' => null,
        ), $resolvedMarket);
    }

