    private function do_fetch_my_trades(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * fetch all trades made by the user
         *
         * @see https://api.bit2me.com/docs/pro/api-reference/trading/v1/trading/trade/get
         *
         * @param {string} [$symbol] unified $market $symbol
         * @param {int} [$since] the earliest time in ms to fetch trades for
         * @param {int} [$limit] the maximum number of trade structures to retrieve, default 50, max 50
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {int} [$params->until] the latest time in ms to fetch trades for
         * @param {int} [$params->offset] the number of trades to skip, for pagination
         * @return {Trade[]} a list of [trade structures](https://docs.ccxt.com/#/?id=trade-structure)
         */
        Async\await($this->load_markets());
        $market = null;
        $request = array();
        if ($symbol !== null) {
            $market = $this->market($symbol);
            $request['symbol'] = $market['id'];
        }
        if ($limit !== null) {
            $request['limit'] = min($limit, 50);
        }
        list($until, $query) = $this->handle_param_integer($params, 'until');
        // startTime and endTime must always be sent together
        if (($since !== null) || ($until !== null)) {
            $start = ($since !== null) ? $since : 0;
            $request['startTime'] = $this->iso8601($start);
            if ($until !== null) {
                $request['endTime'] = $this->iso8601($until);
            } else {
                $request['endTime'] = $this->iso8601($this->milliseconds());
            }
        }
        $response = Async\await($this->privateGetV1TradingTrade($this->extend($request, $query)));
        //
        //     {
        //         "data": [
        //             {
        //                 "amount": 0.24,
        //                 "amountCurrency": "BTC",
        //                 "clientOrderId": null,
        //                 "cost": 15600.12,
        //                 "costEuro": 15600.12,
        //                 "createdAt": "2024-05-07T14:09:02.310Z",
        //                 "feeAmount": 15.60012,
        //                 "feeCurrency": "EUR",
        //                 "feePercentage": 0.1,
        //                 "id": "4278a86a-53e7-4997-9102-01646ae8954a",
        //                 "isMaker": true,
        //                 "orderId": "536ee1dc-528a-419e-9c00-5e04c010658d",
        //                 "orderType": "limit",
        //                 "price": 65000.5,
        //                 "priceCurrency": "EUR",
        //                 "side": "buy",
        //                 "symbol": "BTC/EUR"
        //             }
        //         ],
        //         "total": 12
        //     }
        //
        $data = $this->safe_list($response, 'data', array());
        return $this->parse_trades($data, $market, $since, $limit);
    }

    public function fetch_order_trades(string $id, ?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_order_trades(...))($id, $symbol, $since, $limit, $params);
    }

    private function do_fetch_order_trades(string $id, ?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * fetch all the trades made from a single order
         *
         * @see https://api.bit2me.com/docs/pro/api-reference/trading/v1/trading/order/id/trades/get
         *
         * @param {string} $id order $id
         * @param {string} [$symbol] unified $market $symbol
         * @param {int} [$since] the earliest time in ms to fetch trades for
         * @param {int} [$limit] the maximum number of trades to retrieve
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array[]} a list of [trade structures](https://docs.ccxt.com/#/?$id=trade-structure)
         */
        Async\await($this->load_markets());
        $market = null;
        if ($symbol !== null) {
            $market = $this->market($symbol);
        }
        $request = array(
            'id' => $id,
        );
        $response = Async\await($this->privateGetV1TradingOrderIdTrades($this->extend($request, $params)));
        //
        //     [
        //         {
        //             "amount": 0.24,
        //             "amountCurrency": "BTC",
        //             "clientOrderId": null,
        //             "cost": 15600.12,
        //             "costEuro": 15600.12,
        //             "createdAt": "2024-05-07T14:09:02.310Z",
        //             "feeAmount": 15.60012,
        //             "feeCurrency": "EUR",
        //             "feePercentage": 0.1,
        //             "feePercentageDiscount": 0,
        //             "id": "4278a86a-53e7-4997-9102-01646ae8954a",
        //             "isMaker": true,
        //             "orderId": "536ee1dc-528a-419e-9c00-5e04c010658d",
        //             "orderType": "limit",
        //             "price": 65000.5,
        //             "priceCurrency": "EUR",
        //             "side": "buy",
        //             "spaceCenterLevelId": null,
        //             "symbol": "BTC/EUR"
        //         }
        //     ]
        //
        return $this->parse_trades($response, $market, $since, $limit);
    }

    public function transfer(string $code, float $amount, string $fromAccount, string $toAccount, $params = array()): PromiseInterface {
        return Async\async(self::do_transfer(...))($code, $amount, $fromAccount, $toAccount, $params);
    }

    private function do_transfer(string $code, float $amount, string $fromAccount, string $toAccount, $params = array()) {
        /**
         * $transfer $currency internally between the bit2me wallet and the trading (pro) wallet
         *
         * @see https://api.bit2me.com/docs/pro/api-reference/funding/v1/trading/wallet/deposit/post
         * @see https://api.bit2me.com/docs/pro/api-reference/funding/v1/trading/wallet/withdraw/post
         *
         * @param {string} $code unified $currency $code
         * @param {float} $amount amount to $transfer
         * @param {string} $fromAccount 'funding' (the bit2me wallet) or 'spot' (the trading wallet)
         * @param {string} $toAccount 'funding' (the bit2me wallet) or 'spot' (the trading wallet)
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a [$transfer structure](https://docs.ccxt.com/#/?id=$transfer-structure)
         */
        Async\await($this->load_markets());
        $currency = $this->currency($code);
        $accountsByType = $this->safe_dict($this->options, 'accountsByType', array());
        $fromId = $this->safe_string($accountsByType, $fromAccount, $fromAccount);
        $toId = $this->safe_string($accountsByType, $toAccount, $toAccount);
        $request = array(
            'currency' => $currency['id'],
            'amount' => $this->currency_to_precision($code, $amount),
        );
        $response = null;
        if (($fromId === 'wallet') && ($toId === 'trading')) {
            $response = Async\await($this->privatePostV1TradingWalletDeposit($this->extend($request, $params)));
        } elseif (($fromId === 'trading') && ($toId === 'wallet')) {
            $response = Async\await($this->privatePostV1TradingWalletWithdraw($this->extend($request, $params)));
        } else {
            throw new BadRequest($this->id . ' transfer() only supports transfers between the funding account (bit2me wallet) and the spot account (trading wallet)');
        }
        //
        //     {
        //         "balance": 1350.5,
        //         "blockedBalance": 0,
        //         "createdAt": "2023-09-13T14:05:42.149Z",
        //         "currency": "EUR",
        //         "id": "3a9f1c2d-7e4b-4f6a-8c1d-2b3e4f5a6b7c",
        //         "rawBalance": "1350.5",
        //         "rawBlockedBalance": "0",
        //         "userId": "2bf436fc-43e6-459a-b647-6b446f72ad96"
        //     }
        //
        $transfer = $this->parse_transfer($response, $currency);
        $transfer['amount'] = $amount;
        $transfer['fromAccount'] = $fromAccount;
        $transfer['toAccount'] = $toAccount;
        return $transfer;
    }

    public function fetch_transfers(?string $code = null, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_transfers(...))($code, $since, $limit, $params);
    }

    private function do_fetch_transfers(?string $code = null, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * fetch the history of movements between the bit2me wallet and the trading (pro) wallet
         *
         * @see https://api.bit2me.com/docs/pro/api-reference/funding/v1/trading/movement/get
         *
         * @param {string} [$code] unified $currency $code of the $currency transferred
         * @param {int} [$since] the earliest time in ms to fetch transfers for
         * @param {int} [$limit] the maximum number of transfer structures to retrieve, default 100, max 100
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {int} [$params->until] the latest time in ms to fetch transfers for
         * @param {string} [$params->movementType] 'deposit' or 'withdrawal', to fetch only one direction
         * @return {array[]} a list of [transfer structures](https://docs.ccxt.com/#/?id=transfer-structure)
         */
        Async\await($this->load_markets());
        $currency = null;
        $request = array();
        if ($code !== null) {
            $currency = $this->currency($code);
            $request['currency'] = $currency['id'];
        }
        if ($since !== null) {
            $request['from'] = $this->iso8601($since);
        }
        if ($limit !== null) {
            $request['limit'] = min($limit, 100);
        }
        list($until, $query) = $this->handle_param_integer($params, 'until');
        if ($until !== null) {
            $request['to'] = $this->iso8601($until);
        }
        $response = Async\await($this->privateGetV1TradingMovement($this->extend($request, $query)));
        //
        //     [
        //         {
        //             "amount": 100,
        //             "createdAt": "2025-03-10T09:30:00.000Z",
        //             "currency": "EUR",
        //             "id": "1b2c3d4e-5f60-4718-9a2b-3c4d5e6f7a8b",
        //             "movementType": "deposit",
        //             "serviceOrderName": "wallet",
        //             "status": "completed",
        //             "walletId": "3a9f1c2d-7e4b-4f6a-8c1d-2b3e4f5a6b7c"
        //         }
        //     ]
        //
        return $this->parse_transfers($response, $currency, $since, $limit);
    }

    public function parse_transfer(array $transfer, ?array $currency = null): array {
        //
        // transfer
        //
        //     {
        //         "balance": 1350.5,
        //         "blockedBalance": 0,
        //         "createdAt": "2023-09-13T14:05:42.149Z",
        //         "currency": "EUR",
        //         "id": "3a9f1c2d-7e4b-4f6a-8c1d-2b3e4f5a6b7c",
        //         "rawBalance": "1350.5",
        //         "rawBlockedBalance": "0",
        //         "userId": "2bf436fc-43e6-459a-b647-6b446f72ad96"
        //     }
        //
        // fetchTransfers
        //
        //     {
        //         "amount": 100,
        //         "createdAt": "2025-03-10T09:30:00.000Z",
        //         "currency": "EUR",
        //         "id": "1b2c3d4e-5f60-4718-9a2b-3c4d5e6f7a8b",
        //         "movementType": "deposit",
        //         "serviceOrderName": "wallet",
        //         "status": "completed",
        //         "walletId": "3a9f1c2d-7e4b-4f6a-8c1d-2b3e4f5a6b7c"
        //     }
        //
        $currencyId = $this->safe_string($transfer, 'currency');
        $movementType = $this->safe_string($transfer, 'movementType');
        $accountsById = $this->safe_dict($this->options, 'accountsById', array());
        $fromAccount = null;
        $toAccount = null;
        $id = null;
        $timestamp = null;
        $status = null;
        if ($movementType !== null) {
            // a movement from the historical list
            $id = $this->safe_string($transfer, 'id');
            $timestamp = $this->parse8601($this->safe_string($transfer, 'createdAt'));
            $status = $this->parse_transfer_status($this->safe_string($transfer, 'status'));
            $wallet = $this->safe_string($accountsById, 'wallet');
            $trading = $this->safe_string($accountsById, 'trading');
            $fromAccount = ($movementType === 'deposit') ? $wallet : $trading;
            $toAccount = ($movementType === 'deposit') ? $trading : $wallet;
        } else {
            // the trading wallet returned by deposit/withdraw, createdAt is the wallet creation date
            $status = 'ok';
        }
        return array(
            'info' => $transfer,
            'id' => $id,
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'currency' => $this->safe_currency_code($currencyId, $currency),
            'amount' => $this->safe_number($transfer, 'amount'),
            'fromAccount' => $fromAccount,
            'toAccount' => $toAccount,
            'status' => $status,
        );
    }

    public function parse_transfer_status(?string $status): ?string {
        $statuses = array(
            'completed' => 'ok',
            'pending' => 'pending',
            'failed' => 'failed',
            'cancelled' => 'canceled',
        );
        return $this->safe_string($statuses, $status, $status);
    }

    public function nonce(): int {
        // the nonce must be a unix timestamp in milliseconds, within 5 seconds of the server clock
        return $this->milliseconds();
    }

    public function sign(string $path, array $api = array('public'), string $method = 'GET', $params = array()): array {
        $apiName = $api[0];
        $requestHeaders = null;
        $requestBody = null;
        $query = $this->omit($params, $this->extract_params($path));
        $url = '/' . $this->implode_params($path, $params);
        $isGetOrDelete = ($method === 'GET') || ($method === 'DELETE');
        if ($isGetOrDelete) {
            if (count($query) > 0) {
                $url .= '?' . $this->urlencode($query);
            }
        }
        if ($apiName === 'private') {
            $this->check_required_credentials();
            // https://api.bit2me.com/docs/guides/authentication
            // message = nonce:path[:compactJsonBody] -> sha256 (binary) -> hmac-sha512 (base64)
            $nonce = (string) $this->nonce();
            $message = $nonce . ':' . $url;
            if (!$isGetOrDelete) {
                // always send a json body, some http clients label an empty body as octet-stream and the gateway rejects it
                // an empty query is spelled out, php encodes an empty array as [] and would sign and post that instead of {}
                if (count($query) > 0) {
                    $requestBody = $this->json($query);
                } else {
                    $requestBody = '{}';
                }
                $message .= ':' . $requestBody;
            }
            $digest = $this->hash($this->encode($message), 'sha256', 'binary');
            $signature = $this->hmac($digest, $this->encode($this->secret), 'sha512', 'base64');
            $requestHeaders = array(
                'x-api-key' => $this->apiKey,
                'x-nonce' => $nonce,
                'api-signature' => $signature,
            );
            if ($requestBody !== null) {
                $requestHeaders['Content-Type'] = 'application/json';
            }
        }
        $apiUrl = $this->safe_string($this->urls['api'], $apiName);
        if ($apiUrl === null) {
            throw new NotSupported($this->id . ' does not have a URL for ' . $apiName . ' endpoints');
        }
        $fullUrl = $apiUrl . $url;
        return array( 'url' => $fullUrl, 'method' => $method, 'body' => $requestBody, 'headers' => $requestHeaders );
    }

    public function handle_errors(int $httpCode, string $reason, string $url, string $method, array $headers, string $body, mixed $response, ?array $requestHeaders, ?string $requestBody): ?bool {
        if ($response === null) {
            return null; // fallback to default error handler
        }
        //
        //     {"statusCode":404,"error":"Not Found","message":"Market not found for symbol FOO/BAR","reqId":"9834b8a8-97b8-470d-ade2-3d31687c0723"}
        //     {"code":403,"description":"invalid credentials"}
        //     {"message":"Validation errors","errors":[{"code":"INVALID_REQUEST_PARAMETER","message":"Invalid parameter (symbol): Value is required but was not provided","in":"query","name":"symbol"}]}
        //     {"message":["type must be one of the following values: all, fiat, crypto"],"error":"Bad Request","statusCode":400}
        //     {"statusCode":412,"error":"Precondition Failed","message":"...","errorPayload":{"code":"ORDER_AMOUNT_LOWER_MARKET_MIN"}}
        //
        $errorCode = $this->safe_string_2($response, 'code', 'statusCode');
        $errorsList = $this->safe_list($response, 'errors');
        $errorPayload = $this->safe_dict($response, 'errorPayload', array());
        $payloadCode = $this->safe_string($errorPayload, 'code');
        if (($errorCode !== null) || ($errorsList !== null) || ($payloadCode !== null)) {
            $message = $this->safe_string_n($response, array( 'message', 'description', 'error' ));
            $feedback = $this->id . ' ' . $body;
            $this->throw_exactly_matched_exception($this->exceptions['exact'], $payloadCode, $feedback);
            $this->throw_broadly_matched_exception($this->exceptions['broad'], $message, $feedback);
            $this->throw_broadly_matched_exception($this->exceptions['broad'], $body, $feedback);
            $this->throw_exactly_matched_exception($this->exceptions['exact'], $errorCode, $feedback);
            throw new ExchangeError($feedback); // unknown message
        }
        return null;
    }
}
